insert into public.sql_assignments(id,title,description,database_name,status)
insert into public.sql_assignment_tasks(id,assignment_id,position,title,instruction,starter_sql,sample_output,order_matters,database_name) values
('21000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001',1,'Top 20 invoice','Tampilkan 20 invoice dengan jumlah terbesar. Jika jumlah sama, urutkan no_invoice menaik.','SELECT ','Kolom: no_invoice, tgl_invoice, jumlah, no_do · 20 baris',true,'latihan1'),
('21000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001',2,'Top invoice Januari 2004','Tampilkan 10 invoice dengan jumlah terbesar pada Januari 2004. Jika jumlah sama, urutkan no_invoice menaik.','SELECT ','Kolom: no_invoice, tgl_invoice, jumlah, no_do · 10 baris',true,'latihan1'),
('21000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000001',3,'Pelanggan paling banyak mengirim','Tampilkan 10 kode pelanggan yang paling banyak melakukan pengiriman berdasarkan tgl_do selama 2003.','SELECT ','Kolom: kode_plg, jumlah_pengiriman · 10 baris',true,'latihan1'),
('21000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000001',4,'Penjualan ekspor tertinggi','Tampilkan 5 nama pelanggan dengan total nilai penjualan Ekspor tertinggi selama 2002–2003 berdasarkan tgl_do.','SELECT ','Kolom: nama_plg, total_penjualan_ekspor · 5 baris',true,'latihan1'),
('21000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000001',5,'Pembeli Tofu terbanyak','Tampilkan 10 nama pelanggan yang membeli produk Tofu (Prd-014) paling banyak berdasarkan total quantity.','SELECT ','Kolom: nama_plg, total_quantity · 10 baris',true,'latihan1'),
('21000000-0000-4000-8000-000000000006','20000000-0000-4000-8000-000000000001',6,'Rata-rata profit produk','Tampilkan 10 produk dengan rata-rata profit tertinggi. Rumus: AVG(total/quantity) - avg_cost.','SELECT ','Kolom: nama_produk, rata_rata_profit · 10 baris',true,'latihan1'),
('21000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000001',7,'Lima transaksi debit terbesar','Tampilkan 5 transaksi dengan saldo debet terbesar pada jurnal2019. Gunakan tgl dan no_bukti sebagai urutan lanjutan.','SELECT ','Seluruh kolom jurnal2019 · 5 baris',true,'latihan'),
('21000000-0000-4000-8000-000000000008','20000000-0000-4000-8000-000000000001',8,'Debit terbesar tanpa transaksi awal','Tampilkan 5 transaksi dengan debet terbesar, selain keterangan Saldo Awal dan Setoran Modal.','SELECT ','Seluruh kolom jurnal2019 · 5 baris',true,'latihan'),
('21000000-0000-4000-8000-000000000009','20000000-0000-4000-8000-000000000001',9,'Debit terbesar beserta nama akun','Tampilkan 5 transaksi terbesar selain Saldo Awal dan Setoran Modal dengan kolom tgl, kode_akun, debet, nama_akun.','SELECT ','Kolom: tgl, kode_akun, debet, nama_akun · 5 baris',true,'latihan'),
('21000000-0000-4000-8000-000000000010','20000000-0000-4000-8000-000000000001',10,'Total debit dan kredit bulanan','Tampilkan jumlah saldo debet dan kredit pada setiap bulan, berurutan dari bulan 1 hingga 12.','SELECT ','Kolom: bulan, total_debet, total_kredit · 12 baris',true,'latihan'),
('21000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000001',11,'Transaksi debit maksimum bulanan','Tampilkan kode akun dan nilai transaksi debit terbesar pada setiap bulan. Sertakan semua hasil jika terdapat nilai maksimum yang sama.','SELECT ','Kolom: bulan, kode_akun, debit_terbesar',true,'latihan'),
('21000000-0000-4000-8000-000000000012','20000000-0000-4000-8000-000000000001',12,'Debit maksimum dan nama akun','Tampilkan transaksi debit terbesar setiap bulan beserta kode_akun dan nama_akun. Sertakan semua nilai maksimum yang sama.','SELECT ','Kolom: bulan, kode_akun, nama_akun, debit_terbesar',true,'latihan'),
('21000000-0000-4000-8000-000000000013','20000000-0000-4000-8000-000000000001',13,'Saldo setiap akun','Tampilkan total debet dan kredit setiap akun, termasuk akun yang tidak memiliki transaksi. Urutkan berdasarkan kode.','SELECT ','Kolom: kode, nama_akun, total_debet, total_kredit · 53 baris',true,'latihan')
insert into public.sql_task_solutions(task_id,solution_sql) values
('21000000-0000-4000-8000-000000000001','SELECT * FROM master_invoice ORDER BY jumlah DESC, no_invoice LIMIT 20'),
('21000000-0000-4000-8000-000000000002','SELECT * FROM master_invoice WHERE tgl_invoice >= ''2004-01-01'' AND tgl_invoice < ''2004-02-01'' ORDER BY jumlah DESC, no_invoice LIMIT 10'),
('21000000-0000-4000-8000-000000000003','SELECT kode_plg, COUNT(*) AS jumlah_pengiriman FROM deliveryorder_master WHERE tgl_do >= ''2003-01-01'' AND tgl_do < ''2004-01-01'' GROUP BY kode_plg ORDER BY jumlah_pengiriman DESC, kode_plg LIMIT 10'),
('21000000-0000-4000-8000-000000000004','SELECT c.nama_plg, SUM(d.total_sales) AS total_penjualan_ekspor FROM customer_master c JOIN deliveryorder_master d ON d.kode_plg=c.kode_plg WHERE d.jenis_sales=''Ekspor'' AND d.tgl_do >= ''2002-01-01'' AND d.tgl_do < ''2004-01-01'' GROUP BY c.kode_plg,c.nama_plg ORDER BY total_penjualan_ekspor DESC,c.nama_plg LIMIT 5'),
('21000000-0000-4000-8000-000000000005','SELECT c.nama_plg, SUM(s.quantity) AS total_quantity FROM customer_master c JOIN deliveryorder_master d ON d.kode_plg=c.kode_plg JOIN sales_detail s ON s.no_do=d.no_do WHERE s.kode_produk=''Prd-014'' GROUP BY c.kode_plg,c.nama_plg ORDER BY total_quantity DESC,c.nama_plg LIMIT 10'),
('21000000-0000-4000-8000-000000000006','SELECT p.nama_produk, AVG(s.total/s.quantity)-p.avg_cost AS rata_rata_profit FROM produk_master p JOIN sales_detail s ON s.kode_produk=p.kode_produk GROUP BY p.kode_produk,p.nama_produk,p.avg_cost ORDER BY rata_rata_profit DESC,p.nama_produk LIMIT 10'),
('21000000-0000-4000-8000-000000000007','SELECT * FROM jurnal2019 ORDER BY debet DESC,tgl,no_bukti LIMIT 5'),
('21000000-0000-4000-8000-000000000008','SELECT * FROM jurnal2019 WHERE keterangan NOT IN (''Saldo Awal'',''Setoran Modal'') ORDER BY debet DESC,tgl,no_bukti LIMIT 5'),
('21000000-0000-4000-8000-000000000009','SELECT j.tgl,j.kode_akun,j.debet,b.nama_akun FROM jurnal2019 j JOIN bagan_akun b ON b.kode=j.kode_akun WHERE j.keterangan NOT IN (''Saldo Awal'',''Setoran Modal'') ORDER BY j.debet DESC,j.tgl,j.no_bukti LIMIT 5'),
('21000000-0000-4000-8000-000000000010','SELECT MONTH(tgl) AS bulan,SUM(debet) AS total_debet,SUM(kredit) AS total_kredit FROM jurnal2019 GROUP BY MONTH(tgl) ORDER BY bulan'),
('21000000-0000-4000-8000-000000000011','SELECT MONTH(j.tgl) AS bulan,j.kode_akun,j.debet AS debit_terbesar FROM jurnal2019 j JOIN (SELECT MONTH(tgl) bulan,MAX(debet) nilai FROM jurnal2019 GROUP BY MONTH(tgl)) m ON m.bulan=MONTH(j.tgl) AND m.nilai=j.debet ORDER BY bulan,j.kode_akun'),
('21000000-0000-4000-8000-000000000012','SELECT MONTH(j.tgl) AS bulan,j.kode_akun,b.nama_akun,j.debet AS debit_terbesar FROM jurnal2019 j JOIN (SELECT MONTH(tgl) bulan,MAX(debet) nilai FROM jurnal2019 GROUP BY MONTH(tgl)) m ON m.bulan=MONTH(j.tgl) AND m.nilai=j.debet JOIN bagan_akun b ON b.kode=j.kode_akun ORDER BY bulan,j.kode_akun'),
('21000000-0000-4000-8000-000000000013','SELECT b.kode,b.nama_akun,SUM(j.debet) AS total_debet,SUM(j.kredit) AS total_kredit FROM bagan_akun b LEFT JOIN jurnal2019 j ON j.kode_akun=b.kode GROUP BY b.kode,b.nama_akun ORDER BY b.kode')
