alter table public.sql_assignment_tasks add column if not exists database_name text;

values('20000000-0000-4000-8000-000000000001','Tugas Query SQL — Jurnal & Penjualan','Kumpulan soal query dari Kuis II Section Query SQL dan Tugas Query SQL. Task menggunakan database latihan dan latihan1.','latihan1','published')
on conflict(id) do update set title=excluded.title,description=excluded.description,status='published',updated_at=now();

on conflict(id) do update set title=excluded.title,instruction=excluded.instruction,starter_sql=excluded.starter_sql,sample_output=excluded.sample_output,order_matters=excluded.order_matters,database_name=excluded.database_name;

on conflict(task_id) do update set solution_sql=excluded.solution_sql;
